CREATE TABLE IF NOT EXISTS schema_migration(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile(user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,version INTEGER NOT NULL,data TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,version));
CREATE TABLE IF NOT EXISTS preference(user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,version INTEGER NOT NULL,data TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,version));
CREATE TABLE IF NOT EXISTS invitation(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,guest_id TEXT REFERENCES user(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER,created_at INTEGER NOT NULL,CHECK(owner_id<>guest_id));
CREATE INDEX IF NOT EXISTS invitation_guest ON invitation(guest_id);
CREATE INDEX IF NOT EXISTS invitation_owner ON invitation(owner_id);
CREATE TABLE IF NOT EXISTS consent(invitation_id TEXT NOT NULL REFERENCES invitation(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,version INTEGER NOT NULL,snapshot TEXT NOT NULL,revoked_at INTEGER,created_at INTEGER NOT NULL,PRIMARY KEY(invitation_id,user_id));
CREATE TABLE IF NOT EXISTS report(id TEXT PRIMARY KEY,invitation_id TEXT UNIQUE NOT NULL REFERENCES invitation(id) ON DELETE CASCADE,data TEXT NOT NULL,versions TEXT NOT NULL,created_at INTEGER NOT NULL,ai_state TEXT NOT NULL DEFAULT 'not_requested',ai_data TEXT,ai_attempts INTEGER NOT NULL DEFAULT 0,ai_updated INTEGER);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES user(id) ON DELETE CASCADE,event TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS throttle(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
